public List<Customer> findAll(int offset, int limit, List<CustomerSort> sorts, CustomerFilter filter) {
    requireSanePage(offset, limit);
    List<Customer> page = filterCustomers(filter).stream()
            .sorted(comparatorFor(sorts))
            .skip(offset).limit(limit).toList();
    queryLog.recordPage(offset, limit, page.size());
    return page;
}

public int count(CustomerFilter filter) {
    int total = filterCustomers(filter).size();
    queryLog.recordCount(total);
    return total;
}

private List<Customer> filterCustomers(CustomerFilter filter) {
    if (filter == null || filter.isEmpty()) return customers;
    Predicate<Customer> namePredicate = namePredicate(filter.name());
    Set<CustomerStatus> statuses = Set.copyOf(filter.statuses()); // note: empty
    return customers.stream()
        .filter(namePredicate)
        .filter(c -> statuses.isEmpty() || statuses.contains(c.status()))
        .toList();
}
```

