private List<Customer> matchingCustomers(CustomerFilter filter) {
    if (filter.isEmpty()) {
        return customers;
    }
    Predicate<Customer> nameMatches = nameMatches(filter.name());
    return customers.stream()
            .filter(nameMatches)
            .filter(customer -> filter.statuses().isEmpty() || filter.statuses().contains(customer.status()))
            .toList();
}

private static Predicate<Customer> nameMatches(String name) {
    List<String> terms = Arrays.stream(name.split("\\s+"))
            .filter(term -> !term.isEmpty())
            .map(CustomerRepository::normalize)
            .toList();
    if (terms.isEmpty()) {
        return customer -> true;
    }
    return customer -> terms.stream().allMatch(term ->
            normalize(customer.firstName()).contains(term)
                    || normalize(customer.lastName()).contains(term));
}

/** Case- and accent-insensitive form of the given text. */
private static String normalize(String text) {
    String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
    return decomposed.replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
}
