private static Set<CustomerStatus> parseStatuses(List<String> values) {
    Set<CustomerStatus> result = new LinkedHashSet<>();
    if (values == null) {
        return result;
    }
    for (String value : values) {
        if (value == null) continue;
        for (String token : value.split(",")) {
            String name = token.trim();
            if (name.isEmpty()) {
                continue;
            }
            try {
                result.add(CustomerStatus.valueOf(name.toUpperCase(Locale.ROOT)));
            } catch (IllegalArgumentException ignored) {
                // Ignore unknown status names in the URL
            }
        }
    }
    return result;
}
