+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.util.List;
+
+/**
+ * A filter for the customer queries served by {@link CustomerRepository}.
+ *
+ * @param name     the name text matched against first and last names; may be
+ *                 blank, which matches every customer
+ * @param statuses the statuses to keep; empty means every status
+ */
+public record CustomerFilter(String name, List<CustomerStatus> statuses) implements Serializable {
+
+    public CustomerFilter {
+        name = name == null ? "" : name.strip();
+        statuses = statuses == null ? List.of() : List.copyOf(statuses);
+    }
+
+    /** A filter that matches every customer. */
+    public static CustomerFilter none() {
+        return new CustomerFilter("", List.of());
+    }
+
+    /** Whether the filter narrows the data set at all. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+}
